#include "defines.hpp"

// include benchmark-specific definitions
#include "atax.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: m x n, row-major (i = row, j = column)
	DEFINE_PROTO_STRUCT(A_layout, j_vec ^ i_vec);
	// x: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(x_layout, j_vec);
	// y: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(y_layout, j_vec);
	// tmp: length m (dimension 'i')
	DEFINE_PROTO_STRUCT(tmp_layout, i_vec);
} tuning;

// Array initialization
void init_array(auto A, auto x) {
	using namespace noarr;

	// x: j dimension of length N
	auto n_len = x | get_length<'j'>();
	num_t fn = static_cast<num_t>(n_len);

	// x[j] = 1 + (j / fn)
	traverser(x).for_each([=](auto state) {
		auto j = get_index<'j'>(state);
		x[state] = static_cast<num_t>(1) + static_cast<num_t>(j) / fn;
	});

	// A: dimensions i (M) and j (N)
	auto m_len = A | get_length<'i'>();
	auto n_len_A = A | get_length<'j'>();

	// A[i][j] = ((i + j) % n) / (5 * m)
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		num_t numerator = static_cast<num_t>((i + j) % n_len_A);
		num_t denom = static_cast<num_t>(5 * m_len);
		A[state] = numerator / denom;
	});
}

// Main computational kernel
//
// Original algorithm (for each i):
//   tmp[i] = 0;
//   for j: tmp[i] += A[i,j] * x[j];
//   for j: y[j]   += A[i,j] * tmp[i];
//
// The optimized version below keeps the same arithmetic and iteration
// order in (i,j), but:
//   - keeps tmp[i] in a scalar accumulator 'acc' (register) and writes
//     it once per row, reducing tmp[] traffic,
//   - tiles the j-dimension using noarr::into_blocks_dynamic to improve
//     cache locality / vectorization friendliness while correctly
//     handling N that is not a multiple of the tile size.
[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	// Tile size along the j-dimension.
	// This is a compile-time constant; into_blocks_dynamic will handle
	// the edge tile when N is not divisible by tile_j.
	constexpr std::size_t tile_j = 256;

	// Create j-blocked views of A, x, and y:
	//   - 'J' is the block index in j,
	//   - 'j' is the index within a block,
	//   - 't' is a presence/guard dimension used by into_blocks_dynamic
	//     to mark valid elements in the (possibly partial) last tile.
	//
	// The physical layout is unchanged; only the index space is
	// transformed.
	auto A_blocked = A ^ into_blocks_dynamic<'j', 'J', 'j', 't'>(lit<tile_j>);
	auto x_blocked = x ^ into_blocks_dynamic<'j', 'J', 'j', 't'>(lit<tile_j>);
	auto y_blocked = y ^ into_blocks_dynamic<'j', 'J', 'j', 't'>(lit<tile_j>);

	#pragma scop
	// 1) y[j] = 0 for all j
	traverser(y).for_each([&](auto sy) {
		y[sy] = static_cast<num_t>(0);
	});

	// 2) Main ATAX kernel: y = A^T * (A * x), with j-tiling.
	//
	// We traverse the blocked views of A, x, y together with tmp so that
	// all shared dimensions ('i', 'J', 'j', 't') are driven by a single
	// traverser.
	auto trav = traverser(A_blocked, x_blocked, y_blocked, tmp);

	// Outer loop over rows i (dimension 'i')
	trav.template for_dims<'i'>([&](auto trav_i) {
		// State with fixed i (only 'i' present); used to access tmp[i].
		auto si = trav_i.state();

		// Phase 1: tmp[i] = sum_j A[i,j] * x[j]
		// We keep the running sum in a scalar 'acc' held in a register.
		num_t acc = static_cast<num_t>(0);

		// Iterate over tiles in j ('J'), then over valid elements in the
		// tile via the guard dimension 't', and finally over 'j' inside
		// each present tile. This visits global j in increasing order:
		//   j = 0..tile_j-1, tile_j..2*tile_j-1, ...
		// exactly matching the original j-loop order.
		trav_i.template for_dims<'J'>([&](auto trav_iJ) {
			trav_iJ.template for_dims<'t'>([&](auto trav_iJt) {
				// Here 't' is fixed to the "present" index (0). Invalid
				// positions in the last tile have length 0 in 't' and
				// are therefore skipped entirely.
				trav_iJt.for_each([&](auto s) {
					// s carries indices (i, J, t, j); A_blocked and
					// x_blocked map these to the correct A[i,j] and x[j].
					acc += A_blocked[s] * x_blocked[s];
				});
			});
		});

		// Write the fully accumulated tmp[i] once.
		tmp[si] = acc;

		// Phase 2: y[j] += A[i,j] * tmp[i]  (tmp[i] == acc)
		// We reuse the same tiling over j so that A and y are
		// accessed in the same block order as in phase 1.
		trav_i.template for_dims<'J'>([&](auto trav_iJ) {
			trav_iJ.template for_dims<'t'>([&](auto trav_iJt) {
				trav_iJt.for_each([&](auto s) {
					y_blocked[s] += A_blocked[s] * acc;
				});
			});
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// common length proto-structure
	auto set_lengths = noarr::set_length<'i'>(m) ^ noarr::set_length<'j'>(n);

	// data structures
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.A_layout   ^ set_lengths);
	auto x   = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout   ^ set_lengths);
	auto y   = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout   ^ set_lengths);
	auto tmp = noarr::bag(noarr::scalar<num_t>() ^ tuning.tmp_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), x.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_atax(A.get_ref(), x.get_ref(), y.get_ref(), tmp.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print result vector y
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, y.get_ref());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
