		auto si = inner_i.state();

		// Keep tmp[i] in a register during the whole dot product.
		num_t tmp_i = static_cast<num_t>(0);

		// View with j split into tiles of size tile_j.
		auto inner_blocked = inner_i.order(
			noarr::into_blocks_dynamic<'j', 'J', 'j', 'b'>(noarr::lit<tile_j>)
