				// s carries indices {i, J, j, b}; A and x only care about 'i' and 'j',
				// and ignore the extra indices.
				tmp_i += A[s] * x[s];
			});
		});

		// Materialize tmp[i] once after finishing the reduction over all tiles.
		tmp[si] = tmp_i;

