	// but we implement it in a cache- and SIMD-friendly way:
	//   - j is the innermost (contiguous) dimension for A, x, y
	//   - we introduce a scalar accumulator acc for tmp[i] kept in a register
	//   - we tile j using into_blocks_dynamic to improve locality for large N,
	//     while still iterating over (i,j) in the same logical order
	//   - we avoid repeatedly loading/storing tmp[i] inside the inner loops.

	// Choose a tile size along j. Using a static literal value here allows the
	// compiler to reason better about loop bounds while keeping the code simple.
	constexpr auto tile_j = noarr::lit<128>;

	#pragma scop
	// ----------------------------------------
	// y[j] = 0 for all j
	// ----------------------------------------
	traverser(y)
		.order(noarr::into_blocks_dynamic<'j', 'J', 'j', 't'>(tile_j))
		.for_each([&](auto sy) {
			y[sy] = static_cast<num_t>(0);
		});

	// ----------------------------------------
	// Main ATAX kernel
	//
	// for (i = 0; i < M; i++) {
	//   tmp[i] = sum_j A[i,j] * x[j];
	//   for (j = 0; j < N; j++)
	//     y[j] += A[i,j] * tmp[i];
	// }
	//
	// We:
	//   - tile the 'j' dimension with into_blocks_dynamic<'j','J','j','t'>
	//   - keep 'i' as the outer dimension (row-wise traversal, row-major friendly)
	//   - use a scalar 'acc' to accumulate tmp[i] in registers
	// ----------------------------------------
	traverser(A, x, y, tmp)
		// Tiling over 'j':
		//   - 'J' is the block index in j
		//   - 't' is a guard dimension for partial tiles
		// The state passed to the lambdas still only contains 'i' and 'j';
		// 'J' and 't' are handled internally by the traverser.
		.order(noarr::into_blocks_dynamic<'j', 'J', 'j', 't'>(tile_j))
		// Outer loop over rows i
		.template for_dims<'i'>([&](auto inner) {
			// 'inner' is a traverser with fixed 'i'
			auto si = inner.state(); // state containing 'i' only

			// Phase 1: tmp[i] = sum_j A[i,j] * x[j]
			// Use a scalar accumulator to keep tmp[i] in a register.
			num_t acc = static_cast<num_t>(0);

			inner.template for_each<'j'>([&](auto state) {
				// state has both 'i' and 'j', but not the tiling dimensions;
				// into_blocks_dynamic only affects the *order* of iteration.
				acc += A[state] * x[state];
			});

			tmp[si] = acc;

			// Phase 2: y[j] += A[i,j] * tmp[i]  (here tmp[i] == acc)
			inner.template for_each<'j'>([&](auto state) {
				y[state] += A[state] * acc;
			});
		});
	#pragma endscop
