//     once per i instead of updated on every j iteration.
//   - We still traverse j in the same global order (0..N-1), so floating‑point
//     results are bit‑identical to the original code.
[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	// Tile size along the j dimension. This is a compile‑time constant chosen
	// so that a tile of A[i, j] for a single row, together with x[j] and y[j],
	// comfortably fits in L1/L2 cache. The exact value can be tuned; 256 is a
	// reasonable default on modern x64 CPUs.
	constexpr std::size_t tile_j = 256;

	#pragma scop

	// 1) y[j] = 0 for all j
	traverser(y).for_each([&](auto sy) {
		y[sy] = static_cast<num_t>(0);
	});

	// 2) Main ATAX computation with j‑tiling and scalar tmp[i] accumulator.
	//
	// We apply into_blocks_dynamic on the 'j' dimension:
	//   - 'J' is the block index (which j‑tile we are in),
	//   - 'j' becomes the index inside the tile,
	//   - 'g' is an internal guard dimension that is empty for positions
	//     that would fall beyond the original N. The traverser automatically
	//     skips states where 'g' is empty, so we don't need manual bounds
	//     checks for the last partial tile.
	//
	// The order(...) call only affects how the traverser walks the structure;
	// it does not change the physical memory layout of A, x, y, or tmp.
	auto tiled_trav =
		traverser(A, x, y, tmp)
			.order(noarr::into_blocks_dynamic<'j', 'J', 'j', 'g'>(tile_j));

	// Outer loop over rows i (unchanged semantic order).
	tiled_trav.template for_dims<'i'>([&](auto trav_i) {
		// State containing only the fixed index i; suitable for indexing tmp.
		auto si = trav_i.state();

		// Scalar accumulator for tmp[i]; lives in registers.
		num_t acc_i = static_cast<num_t>(0);

		// ------------------------------------------------------------------
		// Phase 1 for this row: tmp[i] = sum_j A[i,j] * x[j]
		// ------------------------------------------------------------------
		//
		// We walk all j in blocked order:
		//   for J (tile index)
		//     for (j, g) inside tile   // g handles the partial tile at the end
		//       acc_i += A[i,j] * x[j];
		//
		// The global order of j (0..N-1) within each row is preserved:
		// J increases from 0 upwards, and within each tile the minor j
		// runs from 0..tile_j-1, skipping out-of-range points via 'g'.
		trav_i.template for_dims<'J'>([&](auto trav_iJ) {
			trav_iJ.for_each([&](auto s) {
				// s has dimensions: i, J, j, g
				//  - For A: only 'i' and 'j' are used.
				//  - For x: only 'j' is used.
				acc_i += A[s] * x[s];
			});
		});

		// Write back tmp[i] once.
		tmp[si] = acc_i;

		// ------------------------------------------------------------------
		// Phase 2 for this row: y[j] += A[i,j] * tmp[i]
		// ------------------------------------------------------------------
		//
		// We reuse the same tiling over j to traverse A and y:
		//   for J:
		//     for (j, g):
		//       y[j] += A[i,j] * acc_i;
		//
		// Again, the global update order of y[j] is unchanged compared to
		// the original kernel (same i‑then‑j nesting, just split into tiles).
		trav_i.template for_dims<'J'>([&](auto trav_iJ) {
			trav_iJ.for_each([&](auto s) {
				y[s] += A[s] * acc_i;
			});
		});
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// common length proto-structure
	auto set_lengths = noarr::set_length<'i'>(m) ^ noarr::set_length<'j'>(n);

	// data structures
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.A_layout   ^ set_lengths);
	auto x   = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout   ^ set_lengths);
	auto y   = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout   ^ set_lengths);
	auto tmp = noarr::bag(noarr::scalar<num_t>() ^ tuning.tmp_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), x.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_atax(A.get_ref(), x.get_ref(), y.get_ref(), tmp.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print result vector y
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, y.get_ref());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
